<script setup lang="ts">
import KnowledgeNodeDetail from './KnowledgeNodeDetail.vue';
import {KnowledgeCamera} from './knowledge-camera';
import {KnowledgeLabels} from './knowledge-labels';
import {KnowledgeDrag} from './knowledge-drag';
import {KnowledgeOrbits} from './knowledge-orbits';
import {KnowledgeMotion} from './knowledge-motion';
import {KnowledgeEdgeLayer} from './knowledge-edge-layer';
import {computed,onBeforeUnmount,onMounted,ref,watch,nextTick} from 'vue';
import {Graph,CircleCombo,register,ExtensionCategory,type CircleComboStyleProps,getExtension} from './knowledge-g6';
class KnowledgeCircle extends CircleCombo {protected getExpandedKeySize(a:Required<CircleComboStyleProps> & {knowledgeRadius?:number;knowledgeX?:number;knowledgeY?:number}):[number,number,number]{const r=Number(a.knowledgeRadius)||36;return [r*2,r*2,0];}getComboPosition(a:Required<CircleComboStyleProps> & {knowledgeRadius?:number;knowledgeX?:number;knowledgeY?:number}):[number,number,number]{return [Number(a.knowledgeX)||0,Number(a.knowledgeY)||0,0];}}
if(!getExtension(ExtensionCategory.COMBO,'knowledge-circle'))register(ExtensionCategory.COMBO,'knowledge-circle',KnowledgeCircle);
import {Button,Input,NativeSelect,OverlayScope,StatusNotice,Popover,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {layoutNetwork,validateNetwork,sameNetworkGeometry,groupId,areaColors,nodeWeight,radiusForWeight,type SizeMode} from './knowledge-network';
import type {KnowledgeEntry,KnowledgeEdge,KnowledgeDiff} from './knowledge-model';
const props=defineProps<{nodes:KnowledgeEntry[];edges:KnowledgeEdge[];snapshotId?:string;historical?:boolean;historyPlaying?:boolean;followHistory?:boolean;overview?:boolean}>(),emit=defineEmits<{open:[path:string];select:[path:string];ready:[snapshotId?:string];latest:[];'update:followHistory':[value:boolean];pauseHistory:[];'update:overview':[value:boolean]}>();
const context=useHostContext(),safe=(v:unknown)=>context.value.host.redact(String(v??''));
const root=ref<HTMLElement>(),canvas=ref<HTMLElement>(),selected=ref(''),query=ref(''),area=ref(''),mode=ref<SizeMode>('total'),expanded=ref(new Set<string>()),error=ref(''),maximized=ref(false),fading=ref(false),rendering=ref(false);
let camera:KnowledgeCamera|undefined;const trackingNote=ref(''),frameHighlights=ref<KnowledgeEntry[]>([]);
async function focusHighlight(path:string){emit('pauseHistory');emit('update:overview',false);emit('update:followHistory',true);choose(path);await nextTick();await serial;const point=lastNetwork?.points.find(p=>p.path===path);if(point&&graph&&canvas.value){camera??=new KnowledgeCamera(graph,canvas.value);await camera.focus(point,()=>alive&&selected.value===path);}}
const settingsOpen=ref(false),groupsOpen=ref(false),historyOpen=ref(false);
const sizeLabel=computed(()=>mode.value==='in'?'被引用知识':mode.value==='out'?'引用知识':'关联知识（去重）');
const floating=ref(true);let motion:KnowledgeMotion|undefined;let motionStop=Promise.resolve();let motionPreference:MediaQueryList|undefined;
function stopMotion(reset=true){const stopped=motion?.stop(reset);motion=undefined;if(stopped)motionStop=Promise.all([motionStop,stopped]).then(()=>{});return motionStop;}
function startMotion(){void stopMotion(false);if(graph&&canvas.value&&floating.value&&!motionPreference?.matches&&!document.hidden&&lastNetwork){motion=new KnowledgeMotion(graph,canvas.value,lastNetwork,positions=>{edgeLayer?.updateMotion(positions);labels?.updateMotion(positions);});}}
function visibility(){if(document.hidden)void stopMotion();else schedule();}
let drag:KnowledgeDrag|undefined,orbits:KnowledgeOrbits|undefined,labels:KnowledgeLabels|undefined;
function startDrag(){if(!graph||!canvas.value||!lastNetwork)return;void drag?.destroy();drag=new KnowledgeDrag(canvas.value,graph,lastNetwork,()=>stopMotion(),(n,id)=>{const p=n.points.find(p=>p.id===id)!;edgeLayer?.updateMotion(new Map([[id,p]]));labels?.updateMotion(new Map([[id,p]]));},()=>{if(lastNetwork)edgeLayer?.update({...lastNetwork},colors().muted,selected.value);startMotion();},path=>{choose(path,false);schedule();});}
let initializedExpansion=false;watch(()=>props.nodes,nodes=>{if(!initializedExpansion&&nodes.length){initializedExpansion=true;expanded.value=new Set(nodes.map(groupId));}},{immediate:true});
let rendered=false;
const changes=ref(new Map<string,string>()),removed=ref(0);let lastNodes=new Map<string,string>(),lastSnapshot:string|undefined;
watch(()=>[props.nodes,props.snapshotId] as const,()=>{const next=new Map(props.nodes.map(n=>[n.path,n.contentHash??JSON.stringify(n)]));if(lastSnapshot&&lastSnapshot!==props.snapshotId){changes.value=new Map([...next].filter(([p,h])=>lastNodes.get(p)!==h).map(([p])=>[p,lastNodes.has(p)?'modified':'added']));removed.value=[...lastNodes.keys()].filter(p=>!next.has(p)).length;}lastNodes=next;lastSnapshot=props.snapshotId;},{immediate:true});
let edgeLayer:KnowledgeEdgeLayer|undefined,lastNetwork:ReturnType<typeof layoutNetwork>|undefined,lastPalette='',lastSelected='',geometryNetwork:ReturnType<typeof layoutNetwork>|undefined,lastChanges=new Map<string,string>();
let graph:Graph|undefined,resize:ResizeObserver|undefined,theme:MutationObserver|undefined,alive=true,epoch=0,serial=Promise.resolve();
const filtered=computed(()=>props.nodes.filter(n=>!area.value||n.area===area.value)),areas=computed(()=>[...new Set(props.nodes.map(n=>n.area??'index'))].sort()),current=computed(()=>nodeIndex.value.get(selected.value));
const nodeIndex=computed(()=>new Map(props.nodes.map(n=>[n.path,n])));
const edgeIndex=computed(()=>{const map=new Map<string,KnowledgeEdge[]>();for(const e of props.edges)for(const id of new Set([e.source,e.target])){if(!map.has(id))map.set(id,[]);map.get(id)!.push(e);}return map;});
const searchIndex=computed(()=>props.nodes.map(n=>({n,text:`${n.title} ${n.path} ${n.uid??''}`.toLowerCase()})));
let previous:ReturnType<typeof layoutNetwork>|undefined;
const network=computed(()=>{const next=layoutNetwork(filtered.value,props.edges,expanded.value,mode.value,previous);previous=next;return next;});
const detailTrail=ref<string[]>([]);
function visitRelated(path:string){if(path===selected.value)return;detailTrail.value=[...detailTrail.value,selected.value].slice(-30);choose(path,true,true);}
function detailBack(){const path=detailTrail.value.at(-1);detailTrail.value=detailTrail.value.slice(0,-1);if(path)choose(path,true,true);}
function closeDetail(){selected.value='';detailTrail.value=[];void nextTick(()=>root.value?.querySelector<HTMLInputElement>('[aria-label="查找图谱文档"]')?.focus());}
const related=computed(()=>edgeIndex.value.get(selected.value)??[]);
const matches=computed(()=>{const q=query.value.toLowerCase(),result:KnowledgeEntry[]=[];for(const {n,text} of searchIndex.value)if(text.includes(q)){result.push(n);if(result.length===30)break;}return result;});
function cancelTracking(){camera?.cancel();}
function manualCamera(event:Event){if((event.target as Element)?.closest('.kb-playback-focus,[data-preserve-history-view]'))return;if((event.target as Element)?.closest('.kb-network,.kb-canvas-tools')&&(props.historyPlaying||props.historical)){cancelTracking();emit('update:followHistory',false);emit('update:overview',false);}}
async function presentChanges(diff:KnowledgeDiff,follow:boolean,valid:()=>boolean){
 cancelTracking();await nextTick();await serial;if(!alive||!valid())return;
 changes.value=new Map(diff.changes.filter(c=>c.kind!=='deleted').map(c=>[c.path,c.kind==='added'?'added':'modified']));removed.value=diff.changes.filter(c=>c.kind==='deleted').length;
 const paths=[...changes.value.keys(),...(diff.relationsAdded??[]).flatMap(e=>[e.source,e.target]),...(diff.relationsRemoved??[]).flatMap(e=>[e.source,e.target])];const candidates=[...new Set(paths)].map(path=>nodeIndex.value.get(path)).filter((n):n is KnowledgeEntry=>!!n).sort((a,b)=>Number(b.area==='decisions')-Number(a.area==='decisions')||nodeWeight(b)-nodeWeight(a)||a.path.localeCompare(b.path));
 frameHighlights.value=candidates.slice(0,3);
 trackingNote.value=candidates.length?'本帧变化 '+candidates.length+' 个节点':removed.value?'本帧删除 '+removed.value+' 个节点，可在更新列表打开删除前版本':'本帧无可定位的节点变化';
 if(follow&&props.followHistory!==false&&candidates[0])choose(candidates[0].path,false);schedule();await nextTick();await serial;if(!alive||!valid())return;
 if(props.overview&&!follow&&graph&&canvas.value&&lastNetwork){camera??=new KnowledgeCamera(graph,canvas.value);await camera.overview(lastNetwork.groups,()=>alive&&valid()&&!!props.overview);canvas.value.dataset.historyView='overview';canvas.value.dataset.trackingZoom=String(graph.getZoom());return;}
 if(!follow||props.followHistory===false)return;
 const point=lastNetwork?.points.find(p=>p.path===candidates[0]?.path);if(!point||!graph||!canvas.value)return;if(!camera)camera=new KnowledgeCamera(graph,canvas.value);canvas.value.dataset.historyView='focus';canvas.value.dataset.trackedNode=point.path;await camera.focus(point,()=>alive&&valid()&&props.followHistory!==false);if(alive&&canvas.value)canvas.value.dataset.trackingZoom=String(graph.getZoom());
}
defineExpose({choose,presentChanges,cancelTracking});
function closeHistory(){historyOpen.value=false;void nextTick(()=>root.value?.querySelector<HTMLButtonElement>('[data-history-toggle]')?.focus());}
function expandAll(open:boolean){previous=undefined;rendered=false;expanded.value=open?new Set(props.nodes.map(groupId)):new Set();}
function toggle(id:string){const next=new Set(expanded.value);if(next.has(id))next.delete(id);else next.add(id);expanded.value=next;}
function choose(path:string,focus=true,keepTrail=false){if(!keepTrail)detailTrail.value=[];query.value='';selected.value=path;emit('select',path);const n=nodeIndex.value.get(path);if(n){area.value='';if(!expanded.value.has(groupId(n)))expanded.value=new Set([...expanded.value,groupId(n)]);if(focus)void nextTick(()=>serial.then(()=>graph?.focusElement('doc:'+path,false)));}}
function colors(){const el=canvas.value!,style=getComputedStyle(el);const resolve=(name:string,fallback:string)=>{const probe=document.createElement('span');probe.style.color=`var(${name},${fallback})`;el.append(probe);const value=getComputedStyle(probe).color;probe.remove();return value;};return {text:resolve('--ocp-foreground','#333'),background:resolve('--ocp-background','#fff'),muted:resolve('--ocp-muted','#888'),font:style.fontFamily};}
function schedule(){const dragging=drag?.destroy();drag=undefined;const stopped=stopMotion();rendering.value=true;const token=++epoch;serial=serial.catch(()=>{}).then(async()=>{await dragging;await stopped;if(!alive||token!==epoch||!canvas.value)return;try{const rect=canvas.value.getBoundingClientRect();if(!rect.width||!rect.height)return;const palette=colors(),paletteKey=JSON.stringify(palette);
 if(graph&&edgeLayer&&(network.value===lastNetwork||sameNetworkGeometry(lastNetwork,network.value))&&paletteKey===lastPalette){
  const updates=[...new Set([lastSelected,selected.value,...lastChanges.keys(),...changes.value.keys()])].filter(p=>p&&nodeIndex.value.has(p)).map(path=>({id:'doc:'+path,style:{stroke:selected.value===path?(props.historical?'#ffd783':palette.text):changes.value.get(path)==='added'?'#278c55':changes.value.has(path)?'#be842b':palette.background,lineWidth:selected.value===path||changes.value.has(path)?3:1,labelText:''}}));
  if(updates.length){graph.updateNodeData(updates);lastSelected=selected.value;lastChanges=new Map(changes.value);await graph.draw();}if(!alive||token!==epoch)return;
  lastNetwork=network.value;labels?.update(network.value,selected.value,safe,props.historical?frameHighlights.value.map(n=>n.path):[]);edgeLayer.update(geometryNetwork!,palette.muted,selected.value);fading.value=false;rendering.value=false;emit('ready',props.snapshotId);startMotion();startDrag();return;
 }
 if(!graph){graph=new Graph({container:canvas.value,width:rect.width,height:rect.height,animation:false,behaviors:['drag-canvas','zoom-canvas'],node:{type:'circle'},edge:{type:'line'},combo:{type:'knowledge-circle'}});graph.on('node:click',e=>{if(!('target' in e)||!e.target||!('id' in e.target))return;const id=String(e.target.id);if(id.startsWith('group:'))toggle(id.slice(6));else if(id.startsWith('doc:'))choose(id.slice(4),false);});graph.on('combo:click',e=>{if('target' in e&&e.target&&'id' in e.target)toggle(String(e.target.id).slice(6));});}
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced&&!props.historical){fading.value=true;await new Promise(r=>setTimeout(r,100));}if(!alive||token!==epoch)return;
 const n=network.value;if(!edgeLayer)edgeLayer=new KnowledgeEdgeLayer(canvas.value,graph);if(!validateNetwork(n))throw Error('overlapping_layout');lastNetwork=undefined;graph.setData({nodes:[...n.points.map(p=>({id:p.id,combo:'combo:'+p.group,data:{path:p.path},style:{x:p.x,y:p.y,size:p.r*2,fill:areaColors[p.entry.area??'index']??'#8b82ac',stroke:selected.value===p.path?(props.historical?'#ffd783':palette.text):changes.value.get(p.path)==='added'?'#278c55':changes.value.has(p.path)?'#be842b':palette.background,lineWidth:selected.value===p.path||changes.value.has(p.path)?3:1,labelText:'',labelFill:palette.text,labelFontFamily:palette.font,labelPlacement:'bottom' as const}})),...n.groups.filter(g=>!g.expanded).map(g=>({id:'group:'+g.id,style:{x:g.x,y:g.y,size:g.r*2,fill:areaColors[g.area]??'#8b82ac',fillOpacity:.22,stroke:areaColors[g.area]??'#8b82ac',labelText:'',labelFill:palette.text,labelFontFamily:palette.font}}))],combos:n.groups.filter(g=>g.expanded).map(g=>({id:'combo:'+g.id,style:{x:g.x,y:g.y,knowledgeX:g.x,knowledgeY:g.y,knowledgeRadius:g.r,padding:24,fill:areaColors[g.area]??'#8b82ac',fillOpacity:.06,stroke:areaColors[g.area]??'#8b82ac',lineWidth:1,labelText:'',labelFill:palette.text,labelPlacement:'top' as const}})),edges:[]});await graph.render();if(!orbits)orbits=new KnowledgeOrbits(canvas.value,graph);orbits.update(n);if(!alive||token!==epoch)return;if(!rendered){await graph.fitView(undefined,false);rendered=true;}edgeLayer?.update(n,palette.muted,selected.value);if(!labels)labels=new KnowledgeLabels(canvas.value,graph);labels.update(n,selected.value,safe,props.historical?frameHighlights.value.map(n=>n.path):[]);lastNetwork=n;geometryNetwork=n;lastChanges=new Map(changes.value);lastPalette=paletteKey;lastSelected=selected.value;canvas.value.dataset.renderedNodes=String(graph.getNodeData().length);canvas.value.dataset.edgeSegments=String(n.edges.length);canvas.value.dataset.edgeRelationships=String(n.edges.reduce((s,e)=>s+e.count,0));fading.value=false;rendering.value=false;error.value='';emit('ready',props.snapshotId);startMotion();startDrag();}catch{lastNetwork=undefined;if(alive){fading.value=false;rendering.value=false;error.value='图谱绘制失败，可刷新重试；目录和正文仍可使用。';}}});}
async function fullscreen(){if(document.fullscreenElement){await document.exitFullscreen();return;}try{await root.value?.requestFullscreen();}catch{maximized.value=!maximized.value;}}
function key(e:KeyboardEvent){if(e.key==='Escape'&&!e.defaultPrevented){if(selected.value){closeDetail();e.preventDefault();}else if(maximized.value)maximized.value=false;}}
watch([network,selected],schedule);watch(()=>props.snapshotId,()=>{selected.value='';detailTrail.value=[];frameHighlights.value=[];});
watch([()=>props.overview,()=>props.followHistory],async()=>{cancelTracking();if(!props.historical)return;const overview=!!props.overview,follow=!!props.followHistory;if(overview)selected.value='';else if(follow&&frameHighlights.value[0])choose(frameHighlights.value[0].path,false);await nextTick();await serial;if(!alive||!graph||!canvas.value||props.overview!==overview||!!props.followHistory!==follow)return;camera??=new KnowledgeCamera(graph,canvas.value);if(overview&&lastNetwork)await camera.overview(lastNetwork.groups,()=>alive&&!!props.overview);else if(follow){const point=lastNetwork?.points.find(p=>p.path===selected.value);if(point)await camera.focus(point,()=>alive&&!!props.followHistory);} });
watch(floating,schedule);
onMounted(()=>{motionPreference=matchMedia('(prefers-reduced-motion: reduce)');motionPreference.addEventListener('change',schedule);document.addEventListener('visibilitychange',visibility);resize=new ResizeObserver(()=>{if(canvas.value&&graph){const r=canvas.value.getBoundingClientRect();if(r.width&&r.height){graph.setSize(r.width,r.height);if(props.overview&&props.historical)void graph.fitView(undefined,false);}edgeLayer?.schedule();orbits?.schedule();labels?.schedule();}else schedule();});if(canvas.value)resize.observe(canvas.value);theme=new MutationObserver(schedule);for(let e:Element|null=root.value??null;e;e=e.parentElement)theme.observe(e,{attributes:true,attributeFilter:['class','style','data-theme']});document.addEventListener('keydown',key);schedule();void nextTick(()=>serial.then(()=>graph?.fitView(undefined,false)));});
onBeforeUnmount(()=>{cancelTracking();void drag?.destroy();orbits?.destroy();labels?.destroy();void stopMotion(false);motionPreference?.removeEventListener('change',schedule);document.removeEventListener('visibilitychange',visibility);alive=false;epoch++;resize?.disconnect();theme?.disconnect();document.removeEventListener('keydown',key);edgeLayer?.destroy();edgeLayer=undefined;graph?.destroy();graph=undefined;});
</script>
<template>
 <section ref="root" class="kb-graph" :class="{maximized,'history-open':historyOpen}" aria-label="知识库图谱" @pointerdown.capture="manualCamera" @wheel.capture.passive="manualCamera"><OverlayScope>
  <div class="kb-graph-toolbar">
   <div class="kb-graph-search"><Input v-model="query" aria-label="查找图谱文档" placeholder="查找知识：标题、路径或 UID" @keydown.esc="query=''"/><div v-if="query" class="kb-matches" role="region" aria-label="图谱搜索结果"><Button v-for="n in matches" :key="n.path" variant="ghost" @click="choose(n.path)">{{safe(n.title)}}</Button><p v-if="!matches.length">没有匹配的知识，试试其他关键词。</p></div></div>
   <NativeSelect v-model="area" aria-label="图谱知识区"><option value="">全部知识区</option><option v-for="a in areas" :key="a" :value="a">{{safe(a)}}</option></NativeSelect>
   <div class="kb-graph-tools">
    <Popover v-model:open="groupsOpen" label="图谱分组"><template #trigger><Button variant="outline" size="sm">分组导航</Button></template><strong>知识分组</strong><div class="kb-panel-actions"><Button variant="outline" size="sm" @click="expandAll(true)">全部展开</Button><Button variant="outline" size="sm" @click="expandAll(false)">全部收起</Button></div><div class="kb-group-navigation"><Button v-for="g in network.groups" :key="g.id" variant="ghost" @click="toggle(g.id)">{{g.expanded?'收起':'展开'}} {{safe(g.label)}} · {{g.count}}</Button></div></Popover>
    <Popover v-model:open="settingsOpen" label="图谱显示设置"><template #trigger><Button variant="outline" size="sm">显示设置</Button></template><strong>图谱显示</strong><label class="kb-setting">节点大小依据<NativeSelect v-model="mode" aria-label="节点大小依据"><option value="total">关联知识（去重）</option><option value="in">被引用数</option><option value="out">引用数</option></NativeSelect></label><div class="kb-size-legend" aria-label="节点大小图例"><span>大小 · {{sizeLabel}}</span><div class="kb-panel-actions"><span v-for="weight in [0,16,100]" :key="weight" class="kb-size-sample"><i :style="{width:radiusForWeight(weight)+'px',height:radiusForWeight(weight)+'px'}"/>{{weight===100?'100+':weight}} 篇</span></div><small>文档：关联越多越大，100 篇起封顶；收起分组：按文档数量显示大小。图示按比例缩小</small></div><strong>颜色 · 知识区</strong><div class="kb-legend"><span v-for="a in areas" :key="a"><i :style="{background:areaColors[a]??'#8b82ac'}"/>{{safe(a)}}</span></div><Button variant="outline" size="sm" :aria-pressed="floating" @click="floating=!floating">{{floating?'暂停漂浮':'开启漂浮'}}</Button></Popover>
    <Button variant="outline" size="sm" data-history-toggle :aria-expanded="historyOpen" @click="historyOpen=!historyOpen">历史回放</Button>
   </div>
  </div>
  <div class="kb-graph-summary"><span>{{nodes.length}} 篇文档 · {{edges.length}} 条关系 · {{network.groups.length}} 个分组</span><span v-if="historical" class="kb-history-state">正在查看历史版本 <Button variant="link" size="sm" @click="historyOpen=false;emit('latest')">返回当前知识库</Button></span><span v-else>当前工作区</span></div>
  <StatusNotice v-if="error" tone="error">{{error}}<Button @click="schedule">重试</Button></StatusNotice>
  <div class="kb-graph-workspace">
   <div ref="canvas" class="kb-network" :data-render-state="rendering?'rendering':'ready'" :class="{fading}" role="img" aria-label="知识图谱画布"/>
   <div class="kb-canvas-tools" role="group" aria-label="画布操作"><Button variant="ghost" size="sm" aria-label="放大图谱" @click="graph?.zoomBy(1.2,false)">放大</Button><Button variant="ghost" size="sm" aria-label="缩小图谱" @click="graph?.zoomBy(.8,false)">缩小</Button><span class="kb-tool-divider"/><Button variant="ghost" size="sm" @click="graph?.fitView(undefined,false)">适应画布</Button><Button variant="ghost" size="sm" data-preserve-history-view @click="fullscreen">全屏 / 退出</Button><Button v-if="maximized" size="sm" data-preserve-history-view @click="maximized=false">退出最大化</Button><div v-if="historyPlaying" class="kb-playback-focus" role="status"><span>{{followHistory?'聚焦跟踪':overview?'全局总览':'自由浏览'}} · {{trackingNote||'准备下一帧'}}</span><Button variant="ghost" size="sm" @click="emit('update:followHistory',!followHistory);emit('update:overview',!!followHistory)">{{followHistory?'全局总览':'聚焦跟踪'}}</Button><Button variant="ghost" size="sm" @click="emit('pauseHistory')">暂停回放</Button></div></div>
   <div v-if="historical&&!current&&frameHighlights.length" class="kb-history-highlights" aria-label="本帧重点变化"><strong>本帧重点变化</strong><p>{{trackingNote}} · 展示前 {{frameHighlights.length}} 项</p><Button v-for="item in frameHighlights" :key="item.path" variant="ghost" @click="focusHighlight(item.path)"><span>{{safe(item.title)}}</span><small>暂停并聚焦 →</small></Button></div>
   <KnowledgeNodeDetail v-if="current" :entry="current" :edges="related" :nodes="nodeIndex" :can-back="!!detailTrail.length" :size-label="sizeLabel" :weight="nodeWeight(current,mode)" :historical="historical" @close="closeDetail" @back="detailBack" @select="visitRelated" @open="emit('open',$event)" @locate="choose($event)"/>
  </div>
  <div class="kb-graph-caption"><Button variant="link" size="sm" @click="settingsOpen=true">{{sizeLabel}}越多，节点越大</Button><span>星系与节点分层环绕 · 拖动探索 · 点击查看详情</span><span>默认显示中心节点汇总关系，选中后显示直接关联</span></div>
  <p v-if="changes.size||removed" class="kb-graph-summary">新增/修改 {{changes.size}}（绿色/琥珀色描边） · 删除 {{removed}}</p>
  <div v-if="historyOpen" class="kb-history-panel"><div class="kb-history-heading"><div><strong>知识演变</strong><p>沿主线历史探索知识的形成与变化</p></div><Button variant="ghost" size="sm" @click="closeHistory">收起历史回放</Button></div><slot name="timeline"/></div>
  <slot name="overlay"/>
 </OverlayScope></section>
</template>
<style scoped>
.kb-graph{background:var(--ocp-background);color:var(--ocp-foreground);min-width:0}.kb-graph:fullscreen,.kb-graph.maximized{padding:20px;width:100%;height:100%;overflow:auto}.kb-graph.maximized{position:fixed;inset:0;z-index:1000}
.kb-graph-toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.kb-graph-search{position:relative;flex:1;min-width:220px}.kb-graph-tools{display:flex;gap:8px;margin-left:auto}.kb-graph-summary{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;font-size:12px;color:var(--ocp-muted);margin:12px 0}.kb-history-state{color:var(--ocp-foreground)}
